const foods=[
{name:T('하카타 라멘','博多ラーメン'),area:A.city,kind:T('돈코츠라멘·면요리','豚骨ラーメン・麺料理'),where:T('후쿠오카시·현내','福岡市・県内'),description:T('진한 돼지뼈 국물과 가는 면, 가에다마 문화로 유명한 후쿠오카 대표 라멘입니다.','濃厚な豚骨スープ、細麺、替え玉文化で知られる福岡を代表するラーメンです。'),source:'https://www.crossroadfukuoka.jp/en/theme/theme4_en'},
{name:T('모쓰나베','もつ鍋'),area:A.city,kind:T('곱창전골·향토','もつ鍋・郷土'),where:T('후쿠오카·하카타','福岡・博多'),description:T('소곱창과 양배추·부추를 간장 또는 된장 베이스 국물에 끓이고 마지막에 면이나 밥을 넣어 먹는 하카타 대표 전골입니다.','牛もつ、キャベツ、ニラを醤油または味噌ベースのスープで煮込み、最後に麺やご飯で締める博多名物の鍋料理です。'),source:'https://www.crossroadfukuoka.jp/en/theme/theme4_en'},
{name:T('미즈타키','水炊き'),area:A.city,kind:T('닭전골·향토','鶏鍋・郷土'),where:T('후쿠오카·하카타','福岡・博多'),description:T('닭을 오래 끓여 만든 뽀얀 국물에 닭고기와 채소를 넣고 폰즈와 함께 먹는 후쿠오카 전통 닭전골입니다.','鶏をじっくり煮出した白濁スープに鶏肉と野菜を入れ、ポン酢で味わう福岡伝統の鶏鍋です。'),source:'https://www.crossroadfukuoka.jp/en/theme/theme4_en'},
{name:T('멘타이코','明太子'),area:A.city,kind:T('명란·기념품','辛子明太子・土産'),where:T('후쿠오카 전역','福岡県全域'),description:T('명태알을 고추 양념액에 숙성한 후쿠오카 대표 식품으로 밥반찬·오니기리·파스타·계란말이 등으로 폭넓게 먹습니다.','スケトウダラの卵を唐辛子入りの調味液で熟成した福岡を代表する食品で、ご飯、 おにぎり、パスタ、卵焼きなど幅広く使われます。'),source:'https://www.crossroadfukuoka.jp/en/theme/theme4_en'},
{name:T('고마사바','ごまさば'),area:A.city,kind:T('고등어회·향토','さば刺身・郷土'),where:T('후쿠오카시','福岡市'),description:T('신선한 생고등어 회를 간장계 양념과 참깨·파 등에 버무려 먹는 후쿠오카의 대표 생선요리입니다.','新鮮な生さばの刺身を醤油だれ、ごま、ねぎなどで和えて食べる福岡を代表する魚料理です。'),source:'https://www.crossroadfukuoka.jp/en/'},
{name:T('모지코 야키카레','門司港焼きカレー'),area:A.kita,kind:T('카레·항구음식','カレー・港町料理'),where:T('모지코','門司港'),description:T('밥과 카레에 치즈·달걀 등을 올려 오븐에서 구워내는 모지코의 대표 지역음식입니다.','ご飯とカレーにチーズや卵などをのせ、オーブンで焼き上げる門司港を代表するご当地料理です。'),source:'https://www.crossroadfukuoka.jp/en/spot/13184'},
{name:T('야나가와 장어 세이로무시','柳川うなぎのせいろ蒸し'),area:A.yana,kind:T('장어·향토','うなぎ・郷土'),where:T('야나가와','柳川'),description:T('양념한 밥 위에 구운 장어와 달걀지단을 올려 세이로에서 다시 쪄내는 야나가와 대표 장어요리입니다.','たれを染み込ませたご飯に焼いたうなぎと錦糸卵をのせ、せいろで蒸し上げる柳川を代表するうなぎ料理です。'),source:'https://www.crossroadfukuoka.jp/en/'},
{name:T('야메차','八女茶'),area:A.yana,kind:T('녹차·전통식품','緑茶・伝統食品'),where:T('야메·지쿠고','八女・筑後'),description:T('특히 교쿠로로 높은 평가를 받는 후쿠오카 남부의 차로, 향이 깊고 감칠맛과 단맛이 풍부합니다.','特に玉露で高く評価される福岡南部のお茶で、香りが深く、うま味と甘みが豊かです。'),source:'https://www.crossroadfukuoka.jp/en/articles/trail'}];
const foodDetails={};for(const f of foods)foodDetails[f.name]={kind:f.kind,taste:T('진한 육수와 신선한 해산물, 달고 깊은 차향이 공존하는 후쿠오카다운 풍미','濃厚な出汁、新鮮な海産物、甘く深い茶の香りが共存する福岡らしい味'),how:T('현지 전문점과 시장에서 대표 조리법으로 맛보고 지역별 차이를 비교해보세요.','現地の専門店や市場で代表的な調理法を味わい、地域ごとの違いを比べてみてください。')};
