const events=[
{id:'f-dontaku',pref:P,name:T('하카타 돈타쿠 미나토 마쓰리','博多どんたく港まつり'),area:A.city,months:[5],timing:T('2026년 5월 3~4일 · 전야제 5월 2일','2026年5月3〜4日・前夜祭5月2日'),scheduleType:T('2026년 공식 일정','2026年公式日程'),type:T('퍼레이드·거리축제·골든위크','パレード・街祭り・ゴールデンウィーク'),description:T('하카타역·메이지도리·텐진 등 도심 곳곳에서 돈타쿠대 퍼레이드와 하나지도샤·연무대가 이어지는 후쿠오카 최대 봄축제입니다.','博多駅、明治通り、天神など市内各所でどんたく隊のパレード、花自動車、演舞台が続く福岡最大の春祭りです。'),source:'https://yokanavi.com/events/274296'},
{id:'f-yamakasa',pref:P,name:T('하카타 기온 야마카사','博多祇園山笠'),area:A.city,months:[7],timing:T('매년 7월 1~15일 · 오이야마 7월 15일 04:59','毎年7月1〜15日・追い山笠7月15日4:59'),scheduleType:T('고정 날짜','固定日'),type:T('야마카사·질주·전통축제','山笠・疾走・伝統祭'),description:T('구시다 신사를 중심으로 약 1t의 가키야마카사를 메고 하카타 거리를 달리는 유네스코 무형문화유산 축제로, 15일 새벽 오이야마가 절정입니다.','櫛田神社を中心に約1トンの舁き山笠を担いで博多の町を走るユネスコ無形文化遺産の祭りで、15日早朝の追い山笠が最高潮です。'),source:'https://yokanavi.com/events/177576'},
{id:'f-miare',pref:P,name:T('무나카타타이샤 미아레 마쓰리','宗像大社みあれ祭'),area:A.muna,months:[10],timing:T('2026년 10월 1일 · 추계대제 10월 1~3일','2026年10月1日・秋季大祭10月1〜3日'),scheduleType:T('2026년 공식 일정','2026年公式日程'),type:T('해상신행·어선행렬·신사','海上神幸・漁船行列・神社'),description:T('100척이 넘는 어선이 대어기를 달고 현해탄을 달리며 무나카타 세 여신을 헤쓰구로 맞이하는 해상신행이 중심인 추계대제입니다.','100隻を超える漁船が大漁旗を掲げ玄界灘を進み、宗像三女神を辺津宮へ迎える海上神幸を中心とした秋季大祭です。'),source:'https://www.crossroadfukuoka.jp/feature/miaresai'},
{id:'f-hakushu',pref:P,name:T('하쿠슈사이 수상 퍼레이드','白秋祭水上パレード'),area:A.yana,months:[11],timing:T('2026년 11월 1~3일','2026年11月1〜3日'),scheduleType:T('2026년 공식 일정','2026年公式日程'),type:T('수상행렬·등불·불꽃','水上行列・灯籠・花火'),description:T('시인 기타하라 하쿠슈를 기리며 밤의 야나가와 수로를 등불과 음악·불꽃 속에서 배로 행진하는 수향도시 특유의 축제입니다.','詩人・北原白秋を偲び、夜の柳川の掘割を灯り、音楽、花火の中で舟が進む水郷ならではの祭りです。'),source:'https://www.crossroadfukuoka.jp/event/12873'},
{id:'f-hina',pref:P,name:T('이즈카 히이나 마쓰리','いいづか雛のまつり'),area:A.chiku,months:[2,3],timing:T('2026년 2월 7일~3월 22일','2026年2月7日〜3月22日'),scheduleType:T('2026년 공식 일정','2026年公式日程'),type:T('히나인형·근대저택·봄행사','雛人形・近代邸宅・春行事'),description:T('구 이토 덴에몬 저택을 중심으로 이즈카 시내 여러 장소에 화려한 히나인형을 전시하는 봄 전통행사입니다.','旧伊藤伝右衛門邸を中心に飯塚市内の複数会場で華やかな雛人形を展示する春の伝統行事です。'),source:'https://www.crossroadfukuoka.jp/en/event/11578'},
{id:'f-light',pref:P,name:T('미야지다케 신사 빛의 길 석양축제','宮地嶽神社 光の道 夕陽のまつり'),area:A.muna,months:[2],timing:T('2026년 2월 19~28일 · 10월에도 전후 기간 개최','2026年2月19〜28日・10月にも前後期間開催'),scheduleType:T('2026년 확인 일정','2026年確認日程'),type:T('석양·신사·특별관람','夕日・神社・特別観覧'),description:T('신사 계단에서 바다까지 이어지는 참배길과 석양이 일직선으로 겹치는 빛의 길을 특별관람과 기도행사로 즐기는 계절 행사입니다.','神社の石段から海まで延びる参道と夕日が一直線に重なる「光の道」を特別観覧や祈願祭で楽しむ季節行事です。'),source:'https://www.crossroadfukuoka.jp/en/spot/11692'}];
const intros={
[P]:['',T('하카타의 대형축제와 음식, 다자이후·무나카타의 고대 신앙, 모지코·고쿠라의 근대도시, 야나가와의 수로와 야메차, 이토시마 해안까지 도시와 역사·바다·먹거리가 매우 촘촘한 규슈의 관문입니다.','博多の大祭と食、太宰府・宗像の古代信仰、門司港・小倉の近代都市、柳川の水路と八女茶、糸島の海岸まで、都市・歴史・海・食が密集する九州の玄関口です。')],
[A.city]:['',T('후쿠오카성터와 오호리공원, 하카타 옛마을·구시다 신사, 모모치 해변과 전망대, 야타이까지 도심 교통만으로 관광과 식도락을 연결하기 좋습니다.','福岡城跡と大濠公園、博多旧市街・櫛田神社、百道浜と展望台、屋台まで、市内交通だけで観光と食をつなぎやすい地域です。')],
[A.daza]:['',T('학문의 신 다자이후텐만구와 규슈국립박물관, 사사구리 순례의 거대한 와불을 연결해 종교와 문화사를 깊게 보기 좋은 근교권입니다.','学問の神・太宰府天満宮、九州国立博物館、篠栗霊場の巨大涅槃像を結び、宗教と文化史を深く見やすい近郊エリアです。')],
[A.ito]:['',T('흰 도리이와 부부바위, 해식동굴·해변·카페가 이어지는 후쿠오카 서쪽의 대표 해안 드라이브·일몰 여행지입니다.','白い鳥居と夫婦岩、海食洞、海岸、カフェが続く福岡西部を代表する海岸ドライブ・夕日エリアです。')],
[A.muna]:['',T('세계유산 무나카타타이샤와 오시마 신앙, 미야지다케 신사의 빛의 길을 통해 현해탄의 고대 해상신앙과 석양을 함께 만나는 지역입니다.','世界遺産の宗像大社と大島信仰、宮地嶽神社の光の道を通して、玄界灘の古代海上信仰と夕景を一緒に感じる地域です。')],
[A.kita]:['',T('모지코의 근대항구 건축과 고쿠라성, 사라쿠라산 야경, 봄 등꽃까지 역사·항구·산 전망을 한 도시권에서 즐길 수 있습니다.','門司港の近代港湾建築、小倉城、皿倉山の夜景、春の藤まで、歴史・港・山の眺望を一つの都市圏で楽しめます。')],
[A.yana]:['',T('수로를 배로 이동하는 야나가와 성하마을과 흰벽 상가·야메차 문화가 이어지는 지쿠고의 대표 전통·식문화 지역입니다.','掘割を舟で進む柳川城下町と、白壁商家・八女茶文化が続く筑後を代表する伝統・食文化エリアです。')],
[A.asa]:['',T('산으로 둘러싸인 아키즈키의 작은 성하마을과 고라산 신앙을 통해 지쿠고 북부의 차분한 역사 풍경을 즐길 수 있습니다.','山に囲まれた秋月の小さな城下町と高良山の信仰を通して、筑後北部の落ち着いた歴史景観を楽しめます。')],
[A.chiku]:['',T('석탄산업으로 번영한 지쿠호의 근대저택과 정원, 산업유산을 통해 규슈 근대화의 생활사를 볼 수 있는 내륙 지역입니다.','炭鉱産業で栄えた筑豊の近代邸宅、庭園、産業遺産を通して、九州近代化の生活史を見られる内陸地域です。')]};
const heroes={[A.city]:2900,[A.daza]:2904,[A.ito]:2907,[A.muna]:2909,[A.kita]:2912,[A.yana]:2916,[A.asa]:2919,[A.chiku]:2921};
const routes=[
{id:'r-2900-0',pref:P,areas:[A.city],title:T('후쿠오카성터와 오호리공원 반나절','福岡城跡と大濠公園 半日'),duration:T('반나절','半日'),intro:T('도심 속 성터와 큰 연못공원을 걸어서 연결해 후쿠오카의 역사와 일상 풍경을 함께 보는 일정입니다.','都心の城跡と大きな池の公園を徒歩で結び、福岡の歴史と日常風景を一緒に見るコースです。'),note:T('벚꽃철에는 마이즈루공원 주변이 매우 혼잡하므로 오전 방문이 좋습니다.','桜の時期は舞鶴公園周辺が非常に混雑するため午前訪問がおすすめです。'),days:[{label:A.city,places:[2900,2901],schedule:[[2900,'09:00',places.find(p=>p.id===2900).activity],[2901,'11:00',places.find(p=>p.id===2901).activity],[null,'12:30',T('텐진·아카사카에서 점심','天神・赤坂で昼食')]]}],image:''},
{id:'r-2900-1',pref:P,areas:[A.city],title:T('하카타 옛마을과 모모치 하루','博多旧市街と百道 1日'),duration:T('1일','1日'),intro:T('구시다 신사에서 하카타 옛마을을 걷고 오후에는 바다와 후쿠오카 타워 전망으로 이동하는 도심 대표 일정입니다.','櫛田神社から博多旧市街を歩き、午後は海と福岡タワーの展望へ移動する市内代表コースです。'),note:T('7월 1~15일 야마카사 기간에는 하카타 구시가지 교통통제와 혼잡을 고려하세요.','7月1〜15日の山笠期間は博多旧市街の交通規制と混雑を考慮してください。'),days:[{label:A.city,places:[2902,2903],schedule:[[2902,'09:30',places.find(p=>p.id===2902).activity],[null,'12:00',T('하카타에서 라멘·고마사바 점심','博多でラーメン・ごまさばの昼食')],[2903,'16:00',places.find(p=>p.id===2903).activity]]}],image:''},
{id:'r-2900-2',pref:P,areas:[A.daza],title:T('다자이후 하루','太宰府 1日'),duration:T('1일','1日'),intro:T('다자이후텐만구의 임시본전 참배와 규슈국립박물관을 걸어서 연결해 신앙과 아시아 교류사를 함께 보는 일정입니다.','太宰府天満宮の仮殿参拝と九州国立博物館を徒歩で結び、信仰とアジア交流史を一緒に見るコースです。'),note:T('2026년 현재 본전은 대수리 중이므로 본래 고혼덴 외관을 기대하기보다 임시본전 자체의 한정 건축을 보는 일정으로 생각하세요.','2026年現在、御本殿は大改修中なので、本来の御本殿外観よりも仮殿の期間限定建築を見る行程と考えてください。'),days:[{label:T('다자이후','太宰府'),places:[2904,2905],schedule:[[2904,'09:30',places.find(p=>p.id===2904).activity],[null,'11:30',T('산도에서 우메가에모치·점심','参道で梅ヶ枝餅・昼食')],[2905,'13:00',places.find(p=>p.id===2905).activity]]}],image:''},
{id:'r-2900-3',pref:P,areas:[A.daza],title:T('난조인 반나절','南蔵院 半日'),duration:T('반나절','半日'),intro:T('후쿠오카 시내에서 JR로 쉽게 접근해 사사구리 순례와 거대한 와불을 보는 짧은 사찰 일정입니다.','福岡市内からJRでアクセスしやすく、篠栗霊場と巨大な涅槃像を見る短い寺院コースです。'),note:T('종교시설이므로 삼각대·과도한 포즈 촬영 등 현장 금지사항을 먼저 확인하세요.','宗教施設のため、三脚や過度なポーズ撮影など現地の禁止事項を先に確認してください。'),days:[{label:T('사사구리','篠栗'),places:[2906],schedule:[[2906,'10:00',places.find(p=>p.id===2906).activity],[null,'12:00',T('사사구리 또는 하카타로 돌아와 점심','篠栗または博多へ戻って昼食')]]}],image:''},
{id:'r-2900-4',pref:P,areas:[A.ito],title:T('이토시마 해안 하루','糸島 海岸1日'),duration:T('1일','1日'),intro:T('게야 해식동굴과 사쿠라이 후타미가우라 일몰을 연결해 이토시마의 바다를 하루 종일 즐기는 드라이브 일정입니다.','芥屋の海食洞と桜井二見ヶ浦の夕日を結び、糸島の海を1日楽しむドライブコースです。'),note:T('게야노오토 유람선은 파도에 따라 결항할 수 있고 대중교통은 촘촘하지 않아 렌터카가 편리합니다.','芥屋の大門遊覧船は波により欠航することがあり、公共交通も多くないためレンタカーが便利です。'),days:[{label:A.ito,places:[2908,2907],schedule:[[2908,'10:30',places.find(p=>p.id===2908).activity],[null,'13:00',T('이토시마 해안에서 해산물·카페 점심','糸島海岸で海鮮・カフェの昼食')],[2907,'17:00',places.find(p=>p.id===2907).activity]]}],image:''},
{id:'r-2900-5',pref:P,areas:[A.muna],title:T('무나카타 세계유산 하루','宗像 世界遺産1日'),duration:T('1일','1日'),intro:T('헤쓰구에서 신보를 보고 페리로 오시마 나카쓰구·요하이쇼까지 이어가며 무나카타 세 여신 신앙을 입체적으로 보는 일정입니다.','辺津宮で神宝を見て、フェリーで大島の中津宮・遥拝所まで進み、宗像三女神信仰を立体的に見るコースです。'),note:T('오시마 올레 코스는 현재 폭우 피해로 임시 폐쇄 중입니다. 신사·요하이쇼만 정규 도로와 섬 교통으로 이동하세요.','大島オルレコースは現在豪雨被害で一時閉鎖中です。神社・遥拝所のみ通常道路と島内交通で移動してください。'),days:[{label:A.muna,places:[2909,2911],schedule:[[2909,'09:00',places.find(p=>p.id===2909).activity],[null,'11:30',T('가미미나토항으로 이동·점심','神湊港へ移動・昼食')],[2911,'13:00',places.find(p=>p.id===2911).activity]]}],image:''},
{id:'r-2900-6',pref:P,areas:[A.muna],title:T('미야지다케 신사 빛의 길 반나절','宮地嶽神社 光の道 半日'),duration:T('반나절','半日'),intro:T('거대한 시메나와와 오쿠노미야를 둘러본 뒤 석양이 참배길과 맞는 시간에 계단 전망을 보는 일정입니다.','巨大なしめ縄と奥之宮を巡り、夕日が参道と重なる時間に石段から展望するコースです。'),note:T('빛의 길 시즌에는 관람구역·정리권·특별기도가 따로 운영되므로 평상시보다 일찍 도착하세요.','光の道シーズンは観覧区域、整理券、特別祈願が別運用となるため通常より早めに到着してください。'),days:[{label:T('후쿠쓰','福津'),places:[2910],schedule:[[2910,'15:00',places.find(p=>p.id===2910).activity]]}],image:''},
{id:'r-2900-7',pref:P,areas:[A.kita],title:T('모지코 레트로 하루','門司港レトロ 1日'),duration:T('1일','1日'),intro:T('JR 모지코역을 중심으로 근대건축과 간몬해협 전망을 도보로 여유 있게 즐기는 항구도시 일정입니다.','JR門司港駅を中心に近代建築と関門海峡の眺望を徒歩でゆっくり楽しむ港町コースです。'),note:T('시모노세키 가라토와 배로 연결할 수도 있어 야마구치 일정과 조합하기 좋습니다.','下関唐戸と船で結ぶこともでき、山口旅行と組み合わせやすいです。'),days:[{label:T('모지코','門司港'),places:[2912],schedule:[[2912,'10:00',places.find(p=>p.id===2912).activity],[null,'12:30',T('모지코 야키카레 점심','門司港焼きカレーの昼食')],[2912,'14:00',T('전망실과 해협 산책을 이어보세요.','展望室と海峡散策を続けてください。')]]}],image:''},
{id:'r-2900-8',pref:P,areas:[A.kita],title:T('고쿠라성과 사라쿠라산 하루','小倉城と皿倉山 1日'),duration:T('1일','1日'),intro:T('고쿠라의 성곽 역사에서 시작해 저녁에는 사라쿠라산 야경으로 마무리하는 기타큐슈 대표 일정입니다.','小倉の城郭史から始め、夕方は皿倉山の夜景で締める北九州の代表コースです。'),note:T('케이블카 운휴일과 야간 막차를 확인하고 일몰 30~60분 전에 정상에 도착하는 편이 좋습니다.','ケーブルカーの運休日と夜の最終便を確認し、日没30〜60分前に山頂へ着くのがおすすめです。'),days:[{label:A.kita,places:[2913,2914],schedule:[[2913,'10:00',places.find(p=>p.id===2913).activity],[null,'13:00',T('고쿠라에서 점심·야하타 이동','小倉で昼食・八幡へ移動')],[2914,'17:00',places.find(p=>p.id===2914).activity]]}],image:''},
{id:'r-2900-9',pref:P,areas:[A.kita],title:T('가와치 등꽃 반나절','河内藤園 半日'),duration:T('반나절','半日'),intro:T('4월 중순~5월 중순의 짧은 개화기에 거대한 등꽃 터널과 등나무棚을 집중해서 보는 계절 일정입니다.','4月中旬〜5月中旬の短い開花期に巨大な藤トンネルと藤棚を集中して楽しむ季節コースです。'),note:T('골든위크 전후 지정기간은 사전예약권 없이는 입장할 수 없으므로 예약 확보 후 이동하세요.','ゴールデンウィーク前後の指定期間は事前予約券なしでは入場できないため、予約確保後に移動してください。'),days:[{label:T('가와치','河内'),places:[2915],schedule:[[2915,'09:30',places.find(p=>p.id===2915).activity],[null,'12:00',T('야하타·고쿠라로 이동해 점심','八幡・小倉へ移動して昼食')]]}],image:''},
{id:'r-2900-10',pref:P,areas:[A.yana],title:T('야나가와 수향 하루','柳川 水郷1日'),duration:T('1일','1日'),intro:T('돈코부네로 수로를 내려가 다치바나가의 저택과 장어 세이로무시까지 묶는 야나가와 정석 일정입니다.','どんこ舟で掘割を下り、立花家の邸宅とうなぎのせいろ蒸しまで組み合わせる柳川の定番コースです。'),note:T('뱃놀이 회사마다 출발·종점이 다르므로 오하나와 연결되는 코스를 선택하면 동선이 편합니다.','川下り会社ごとに出発・終点が異なるため、御花へつながるコースを選ぶと動線が楽です。'),days:[{label:T('야나가와','柳川'),places:[2916,2917],schedule:[[2916,'09:30',places.find(p=>p.id===2916).activity],[null,'11:30',T('장어 세이로무시 점심','うなぎのせいろ蒸しの昼食')],[2917,'13:00',places.find(p=>p.id===2917).activity]]}],image:''},
{id:'r-2900-11',pref:P,areas:[A.yana],title:T('야메 흰벽마을 반나절','八女 白壁の町 半日'),duration:T('반나절','半日'),intro:T('야메후쿠시마의 흰벽 상가와 전통공예·차 문화를 천천히 걸어서 즐기는 일정입니다.','八女福島の白壁商家と伝統工芸・茶文化をゆっくり歩いて楽しむコースです。'),note:T('상점·공방은 휴무일이 서로 다르므로 주말 방문이 선택지가 많습니다.','商店・工房は定休日がそれぞれ異なるため、週末の方が選択肢が多いです。'),days:[{label:T('야메','八女'),places:[2918],schedule:[[2918,'10:00',places.find(p=>p.id===2918).activity],[null,'12:30',T('야메차와 현지 점심','八女茶と地元の昼食')]]}],image:''},
{id:'r-2900-12',pref:P,areas:[A.asa],title:T('아키즈키 성하마을 반나절','秋月城下町 半日'),duration:T('반나절','半日'),intro:T('산으로 둘러싸인 작은 성하마을의 옛 거리와 성터·구로몬을 걸어서 보는 역사 산책입니다.','山に囲まれた小さな城下町の古い町並み、城跡、黒門を徒歩で巡る歴史散策です。'),note:T('벚꽃·단풍 절정기에는 주차와 버스가 혼잡하므로 오전 일찍 방문하세요.','桜・紅葉のピーク時は駐車場とバスが混雑するため朝早く訪れてください。'),days:[{label:T('아키즈키','秋月'),places:[2919],schedule:[[2919,'09:30',places.find(p=>p.id===2919).activity],[null,'12:30',T('아키즈키 마을에서 점심','秋月の町で昼食')]]}],image:''},
{id:'r-2900-13',pref:P,areas:[A.chiku],title:T('지쿠호 근대저택 반나절','筑豊 近代邸宅半日'),duration:T('반나절','半日'),intro:T('석탄산업의 번영을 보여주는 이토 덴에몬 저택과 정원을 통해 지쿠호 근대사를 보는 일정입니다.','炭鉱産業の繁栄を伝える伊藤伝右衛門邸と庭園から筑豊の近代史を見るコースです。'),note:T('수요일 정기휴관과 히나마쓰리 기간의 특별운영을 방문 전 확인하세요.','水曜定休と雛まつり期間の特別運営を訪問前に確認してください。'),days:[{label:A.chiku,places:[2921],schedule:[[2921,'10:00',places.find(p=>p.id===2921).activity],[null,'12:30',T('이즈카에서 점심','飯塚で昼食')]]}],image:''}];
const routePlanning={};for(const r of routes){const d=r.days[0];routePlanning[r.id]={start:places.find(p=>p.id===d.places[0])?.name||'',end:places.find(p=>p.id===d.places.at(-1))?.name||'',move:T('구간별 공식 교통편과 시간표를 확인해 도보·지하철·철도·버스·페리·택시·렌터카를 선택하세요.','区間ごとの公式交通手段と時刻表を確認し、徒歩・地下鉄・鉄道・バス・フェリー・タクシー・レンタカーを選んでください。'),meal:d.schedule.find(x=>x[0]===null)?.[2]||T('일정 중간에 식사·휴식','予定の途中で食事・休憩'),rain:T('해안·섬·꽃 일정은 악천후 시 줄이고 박물관·성·신사·전통거리 중심으로 조정하세요.','海岸・島・花の予定は悪天候時に短縮し、博物館・城・神社・伝統的町並み中心に調整してください。'),skip:T('시간이 부족하면 마지막 장소를 다음 일정으로 미루세요.','時間が足りない場合は最後の場所を次の予定に回してください。'),warning:r.note,schedule:d.schedule}}
